// src/App.js

import React, { useEffect, useRef, useState } from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import axios from 'axios';
import HomePage from './pages/HomePage'; // The new component for your existing logic
import ProductsPage from './pages/ProductsPage'; // Your new products page

function App() {
    return (
        <div>
            <nav style={{ padding: '10px 20px', backgroundColor: '#f4f4f4', borderBottom: '1px solid #ddd' }}>
                <Link to="/" style={{ marginRight: '20px' }}>Home</Link>
                <Link to="/products">Products</Link>
            </nav>

            <Routes>
                {/* Route for the home page (the existing category tree) */}
                <Route path="/" element={<HomePage />} />

                {/* Route for the new products page */}
                <Route path="/products" element={<ProductsPage />} />
            </Routes>
        </div>
    );
}

export default App;
